   java.security.MessageDigest sourceHash=java.security.MessageDigest.getInstance("SHA-256");long count=0;try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(zip())){if(in==null)throw new IOException("Não consegui ler o arquivo escolhido");byte[] b=new byte[1048576];int n;while((n=in.read(b))!=-1){out.write(b,0,n);sourceHash.update(b,0,n);count+=n;if(count>profile.size+profile.block)throw new IOException("Arquivo maior que o ZIP esperado");showProgress("Copiando ZIP",(int)(count/1048576),(int)(profile.size/1048576));}}
